-- Organisations (autocomplete, plan section 19), supervisor search counters (section 20) and request rate counters
-- (section 23). D1 database: wavelength-volunteers.
-- Additive only: new tables, new nullable columns and seed rows. No existing row loses data.
-- NOT applied to production. Apply only with the owner's go-ahead, after recording a Time Travel recovery point.
-- The Worker tolerates this migration being absent (orgsReady() in worker/organisations.js): organisation search
-- answers with no suggestions, typed organisation text is saved as before, and the rate limiter allows requests.

-- 1. The canonical list. Ids are stable Wavelength ids (wl-<n>): seed rows use 1 to 99999, administrators' additions
-- 100001 upwards. ods_code is the NHS Organisation Data Service code where known, for matching a later ODS import;
-- it is never the id. name_norm: see worker/org-norm.js. Nothing is ever deleted: a merge sets status 'merged' and
-- merged_into, so old ids still resolve.
CREATE TABLE IF NOT EXISTS organisations (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  name_norm TEXT NOT NULL,
  kind TEXT NOT NULL,                              -- trust | hospital | health_board | university | deanery | private | other
  parent_id TEXT,                                  -- hospital site -> trust
  country TEXT NOT NULL DEFAULT 'GB',
  status TEXT NOT NULL DEFAULT 'active',           -- active | closed | merged
  merged_into TEXT,
  source TEXT NOT NULL,                            -- seed | ods | admin
  ods_code TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS org_name_norm ON organisations (name_norm);
CREATE INDEX IF NOT EXISTS org_status ON organisations (status);

CREATE TABLE IF NOT EXISTS organisation_aliases (
  organisation_id TEXT NOT NULL,
  alias TEXT NOT NULL,
  alias_norm TEXT NOT NULL,
  created_at TEXT,
  PRIMARY KEY (organisation_id, alias_norm)
);
CREATE INDEX IF NOT EXISTS org_alias_norm ON organisation_aliases (alias_norm);

-- "My organisation is not listed". Shown only to the person who typed it and to administrators; never offered to
-- anyone else until an administrator maps it (which adds an alias) or adds it as a new organisation.
CREATE TABLE IF NOT EXISTS organisation_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  typed TEXT NOT NULL,
  typed_norm TEXT NOT NULL,
  learner_id INTEGER,
  status TEXT NOT NULL DEFAULT 'open',             -- open | mapped | added | dismissed
  organisation_id TEXT,
  decided_by TEXT,
  decided_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS org_requests_status ON organisation_requests (status, id);
CREATE INDEX IF NOT EXISTS org_requests_learner ON organisation_requests (learner_id, status);

-- 2. Each place that stores an organisation keeps its typed text and gains an optional id, set only when the person
-- picked a suggestion or an administrator confirmed a match. (supervisor_applications.organisation_id is in 0012.)
ALTER TABLE learners ADD COLUMN organisation_id TEXT;
ALTER TABLE professional_registrations ADD COLUMN organisation_id TEXT;
ALTER TABLE directory_profiles ADD COLUMN organisation_id TEXT;

-- 3. Supervisor search: searches and requests per account per UK day. Search terms are never stored, only counts.
CREATE TABLE IF NOT EXISTS search_counts (
  learner_id INTEGER NOT NULL,
  day TEXT NOT NULL,
  searches INTEGER NOT NULL DEFAULT 0,
  requests INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (learner_id, day)
);

-- 4. Fallback request counters for worker/ratelimit.js, used only when no Workers rate-limiting binding exists.
-- bucket is '<scope>:<key>:<window>'; IP addresses are stored only as a short hash. Rows expire after their window.
CREATE TABLE IF NOT EXISTS rate_counters (
  bucket TEXT PRIMARY KEY,
  n INTEGER NOT NULL DEFAULT 0,
  expires_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS rate_counters_expiry ON rate_counters (expires_at);

-- 5. Seed list (data/organisations.json).
